=== type.within
`within` answers its block or the deadline it ran past
```
// /w/avra.toml
[package]
name = "app"
version = "0.1.0"
// /w/src/main.av
use @std.time.{ms}
let r = within ms(100) {
    let a = 1
}
0
```
```
=== annotation.meta
the compiler crosses `@std/meta`'s own shapes
```
// /w/avra.toml
[package]
name = "app"
version = "0.1.0"
[dependencies]
"@std/meta" = { path = "vendor/meta" }
"@x/c" = { path = "vendor/c" }
// /w/src/main.av
use @x.c.{plain}
@plain
fn f() -> int { 1 }
f()
=== resolve.private_apart
a test reads a private name its module declares once
```
// /w/avra.toml
[package]
name = "app"
version = "0.1.0"
// /w/src/main.av
1
// /w/src/util/a.av
fn h() -> int { 1 }
// /w/src/util/b.av
fn h() -> int { 2 }
// /w/src/util/tests/u_test.av
use util.{h}
=== resolve.reexport_cycle
a re-export never closes a package cycle
```
// /w/avra.toml
[package]
name = "app"
version = "0.1.0"
// /w/src/main.av
use @std.low.{g}
g()
```
```
