export fn stale_citations(engine: QueryEngine, file: SourceFileAddress) -> List<StaleCitation> {
    let known = known_rule_ids()
    let unbacked = [u with { at: item_start(engine, file, i) + u.at } for i in 0..item_count(engine, file) for u in claims_naming_nothing(read_item(engine, file, i).store.remarks.get(), known)]
    if unbacked.is_empty() { return [] }
    let src = whole_source(engine, file)
    [StaleCitation { line: src.linecol(u.at).line, id: u.id } for u in unbacked]
}
