use diagnostics.{new_source_file}
spec "zz stale probe" {
    then "says" {
        let text = "fn f() -> int { 1 }\n// LICENSED style.no_such_rule: nothing backs it\nf()\n"
        let known = known_rule_ids()
        let src = new_source_file("/c/src/main.av", text)
        let rs = lexed_under(text, [], avra().keywords).remarks
        let n = citations_naming_nothing(src, rs, known)
        println("FOUND>>>known=${known.length} has=${known.contains("style.no_such_rule")} remarks=${rs.length} naming_nothing=${n.length} cites=${cites_nothing("style.no_such_rule", known)}<<<")
        false
    }
}
EOF
