p='/work/avra/packages/std-avrac/src/compiler/item_context_reads.av'; s=open(p).read()
a='''/// The contexts `files` declare.
fn declared_in(engine: QueryEngine, files: List<SourceFileAddress>) -> List<Declared> {
    [Declared { key: context_key(d), name: d.name, required: context_required_of(engine, d) } for f in files for d in file_declares(engine, f).names if d.kind == ItemKind.Ctx]
}'''
assert s.count(a)==1
s=s.replace(a,'''/// The contexts `files` declare.
fn declared_in(engine: QueryEngine, files: List<SourceFileAddress>) -> List<Declared> { flatten([file_contexts(engine, f).contexts for f in files]) }

/// The contexts one file declares, held apart from the rest of what it declares: a use reads the
/// declaration, never its file, so a program's framing reads which contexts its files declare and
/// stands while a file gains, loses or renames anything else.
@derive(Saved)
type FileContexts = { contexts: List<Declared> }

/// The contexts the file `file` declares.
@cut_query
fn file_contexts(engine: QueryEngine, file: SourceFileAddress) -> FileContexts {
    FileContexts {
        contexts: [Declared { key: context_key(d), name: d.name, required: context_required_of(engine, d) } for d in file_declares(engine, file).names if d.kind == ItemKind.Ctx],
    }
}''')
open(p,'w').write(s)
EOF
