// A kept binary is reused only while every tool that made it stands as it
// did: each build mints a fresh workspace, so two builds over one root share
// only the store.
use @std.io.{make_dirs, write_text}
use @std.time.{stamp}
use @std.avrac.compiler.{build_program}
use @std.avrac.compiler.host.{Stamp}
use commands.{root_workspace, toolchain}

/// One directory per run, so no earlier run's cache answers for this one.
once fn run_base() -> string { "/tmp/avra-build-tools-test/${stamp()}" }

/// A program of one line.
fn program(name: string) -> string {
    let r = "${run_base()}/${name}"
    let _ = make_dirs("${r}/src")
    let _ = write_text("${r}/avra.toml", "[package]\nname = \"${name}\"\nversion = \"0.0.1\"\n")
    let _ = write_text("${r}/src/main.av", "1 + 1\n")
    r
}

/// Whether a build of the program at `r`, under the host's own toolchain
/// with `tools` as the tools that made it, reused a kept binary.
fn reused(r: string, tools: List<Stamp>) -> bool? {
    let ws = root_workspace(r)
    let host = match toolchain(ws, "", false, false, false) {
        .Ok(t) -> t,
        .Err(_) -> { return null },
    }
    match build_program(ws, "${r}/src/main.av", host with { tools: tools }) {
        .Ok(b) -> b.reused,
        .Err(_) -> null,
    }
}

fn marked(mark: int?) -> List<Stamp> { [Stamp { path: "/opt/cc", mark: mark }] }

spec "cli build — a kept binary names its tools" {
    given "a toolchain that names no tools" {
        then "no build under it reuses a binary, however often asked" {
            let r = program("none")
            let _ = reused(r, [])
            reused(r, []) == false
        }
    }
    given "a program built twice under one toolchain" {
        then "the second build reuses the first's binary" {
            let r = program("same")
            let _ = reused(r, marked(7))
            reused(r, marked(7)) == true
        }
    }
    given "a program built again after a tool moved" {
        then "the binary is linked again" {
            let r = program("moved")
            let _ = reused(r, marked(7))
            reused(r, marked(8)) == false
        }
    }
    given "a tool the host cannot tell" {
        then "no build reuses a binary it made, however often asked" {
            let r = program("untold")
            let _ = reused(r, marked(null))
            reused(r, marked(null)) == false
        }
        then "a build that names no tools never reuses a binary made under it" {
            let r = program("untold-then-none")
            let _ = reused(r, marked(null))
            reused(r, []) == false
        }
        then "a binary made under it is linked again once the tool can be told" {
            let r = program("told-later")
            let _ = reused(r, marked(null))
            reused(r, marked(7)) == false
        }
    }
}
//! `compiler/idioms.av`'s own rules are declared as `quote { ... } ->
//! ...` patterns whose left side, matched structurally, is a
//! `Pat.Quote` — and that pattern's own text is a CODE SHAPE
//! (`${cx}.emit(Ins.IfStart(${c}))`, say) mirrored into an expr
//! tree so the pattern can be WRITTEN. Before rule_pass.av's
//! `every_at` learned to stop at a `Pat.Quote`, the rules pass
//! walked INTO that mirrored tree the same as any other code, so
//! every rule in this file matched its OWN declaration — a
//! PRECISION bug (avra-8sb5.25.49), not debt: `compiler/idioms.av`
//! had 34 self-matches and exactly one real defect
//! (`most_copied`'s own `mut best: string? = null`, a genuine
//! `nullable_flag_local`, still caught here). Real sites elsewhere
//! (walk.av, interp.av, derive.av, …) are untouched by this fix —
//! `tools/idioms.baseline`'s own before/after is the tree-wide
//! proof; this test pins the file the bug lived in.
use @std.avrac.compiler.{rule_findings, analysed}
use commands.{root_program}

spec "commands/rule pass — a rule never fires on its own pattern" {
    given "compiler/idioms.av, analyzed as part of the real std-avrac package" {
        then "the only finding is the one real defect, never one of the file's 34 self-matching quote patterns" {
            mut p = root_program("packages/std-avrac")
            let hit = p.files.find(it.view.source.file.ends_with("compiler/idioms.av"))
            match hit {
                a? -> {
                    let cands = rule_findings(analysed(a), a.view.stmts)
                    cands.length == 1 && cands[0].kind == "nullable.nullable_flag_local"
                }
                null -> false
            }
        }
    }
}
