cd /work/avra; python3 - <<'EOF'
p='/work/avra/packages/std-avrac/src/compiler/item_scope.av'; s=open(p).read()
old_scope=s[s.index('/// What is `file`\'s own at its top level; absent for a file that isn\'t there.\n@cut_query\nexport fn file_scope('):s.index('/// Every declaration of `name` the module `at` makes:')]
new_scope='''/// What is `file`'s own at its top level; absent for a file that isn't there.
@cut_query
export fn file_scope(engine: QueryEngine, file: SourceFileAddress) -> FileScope? { scope_built(engine, file, true) }

/// What is `file`'s own at its top level among written names alone: an import whose module writes
/// nothing of its name is left pending, never asking what that module's generators make. Generators
/// stand in strata: what a generator is made of and fed never reads what generators make, so the
/// names a generator's own file imports from the module it makes for are asked one by one, as
/// `resolved` reads each — never all at once, under the making of the generator that answers them.
@cut_query
export fn written_file_scope(engine: QueryEngine, file: SourceFileAddress) -> FileScope? { scope_built(engine, file, false) }

/// `file`'s scope, its imports of names their modules don't write bound from what the modules'
/// generators make (`generated`), or left pending.
fn scope_built(engine: QueryEngine, file: SourceFileAddress, generated: bool) -> FileScope? {
    if source_text(engine, file) == null { return null }
    let module = module_kept(engine, file.package_name, module_segments(file), true)
    mut own = nothing_bound()
    for d in module.apart { if same_file(d.file, file) { own.bind(space_of(d.kind), d.name, d) } }
    mut clashes: List<NameClash> = []
    mut pending: List<PendingImport> = []
    for u in file_words(engine, file).uses {
        let at? = imported_module(engine, file, u) else { continue }
        let privately = tests_of(file, at)
        for j, item in u.items {
            let written = declarations_of(engine, at.package, at.local, at.as_root, item)
            if written.is_empty() && !reexports_name(engine, at, item) && !generated {
                pending
                    .push(
                        PendingImport {
                            name: u.bound_as(j),
                            item: item,
                            package: at.package,
                            local: at.local,
                            as_root: at.as_root,
                            privately: privately,
                        },
                    )
                continue
            }
            let ds = if generated { module_declarations_of(engine, at, item) } else { written }
            for d in ds {
                if !d.exported && !(privately && read_privately(ds, d)) { continue }
                let clash = imported(engine, own, file, u.bound_as(j), d)
                if clash != null { clashes.push(clash!) } else { own.bind(space_of(d.kind), u.bound_as(j), d) }
            }
        }
    }
    FileScope {
        own: own,
        siblings: [d for d in module.apart if !same_file(d.file, file)],
        clashes: [c for c in module.clashes if same_file(c.lost.file, file)].concat(clashes),
        pending: pending,
    }
}

/// An import of `item` as `name` from a module that writes nothing of it: what the module's
/// generators make of it, asked only when `name` itself is read (`resolved`).
@derive(Saved)
export type PendingImport = {
    name: string,
    item: string,
    package: string,
    local: List<string>,
    as_root: bool,
    privately: bool,
}

/// What the pending import `p` binds `p.name` to in `space` once its module's generators are asked:
/// as `file_scope` binds it — an export, or a tests module's private read — unless it clashes with
/// what the file already holds, which keeps the name. Absent where they make none of it.
fn pending_bound(engine: QueryEngine, scope: FileScope, file: SourceFileAddress, p: PendingImport, space: Space) -> DeclaredName? {
    let ds = generated_declarations_of(engine, p.package, p.local, p.as_root, p.item)
    let d? = ds.find((d) -> space_of(d.kind) == space && (d.exported || (p.privately && read_privately(ds, d)))) else { return null }
    if imported(engine, scope.own, file, p.name, d) != null { return null }
    d
}

'''
s=s.replace(old_scope,new_scope)
a='export type FileScope = { own: Bound, siblings: List<DeclaredName>, clashes: List<NameClash> }'
assert s.count(a)==1
s=s.replace(a,'export type FileScope = { own: Bound, siblings: List<DeclaredName>, clashes: List<NameClash>, pending: List<PendingImport> = [] }')
a='''export fn resolved(engine: QueryEngine, file: SourceFileAddress, space: Space, name: string) -> Resolution {
    let scope? = file_scope(engine, file) else { return Resolution.Unbound }
    let written = resolved_in(engine, scope, file, space, name)'''
assert s.count(a)==1
s=s.replace(a,'''export fn resolved(engine: QueryEngine, file: SourceFileAddress, space: Space, name: string) -> Resolution {
    let scope? = written_file_scope(engine, file) else { return Resolution.Unbound }
    let p = if scope.own.held(space, name) == null { scope.pending.find(it.name == name) } else { null }
    if p != null {
        let d = pending_bound(engine, scope, file, p!, space)
        if d != null { return Resolution.Named(d!) }
    }
    let written = resolved_in(engine, scope, file, space, name)''')
a='''    let scope? = file_scope(engine, file) else { return Resolution.Unbound }
    resolved_in(engine, scope, file, space, name)
}'''
assert s.count(a)==1
s=s.replace(a,'''    let scope? = written_file_scope(engine, file) else { return Resolution.Unbound }
    resolved_in(engine, scope, file, space, name)
}''')
open(p,'w').write(s)
EOF
