use @std.avrac.testing.{held_at, vendored_meta}
use @std.avrac.testing.held.{empty_store}

fn zz_probe(shown_use: string, main: string) -> string {
    held_at(
        vendored_meta(
            {
                "/w/avra.toml": "[package]
name = "@repro/shown"
version = "0.0.1"

[lib]
name = "repro-shown"
path = "src/shown.av"

[dependencies]
"@std/meta" = { path = "vendor/meta" }
",
                "/w/src/shown.av": "use @std.meta.{Type, Declared, beside, derive, literal}
${shown_use}
export trait Shown {
    fn shown() -> string

    static fn derive(t: Type) -> Declared {
        Declared { made: [beside(t, quote { impl Shown for \${t} { fn shown() -> string { "x" } } })] }
    }
}
",
                "/w/src/parts.av": "use @std.meta.{derive}
use shown.{Shown}

@derive(Shown)
export type Part = { id: int }
",
                "/w/src/main.av": main,
            },
        ),
        "/w",
    )
        .checked_over(empty_store())
}

spec "zz cycle probe" {
    then "a: the derive's file imports a missing name from the module it derives over" { println("A>>>${zz_probe("use parts.{gone}
", "1
")}<<<") false }
    then "b: another file imports a missing name from the derived module" { println("B>>>${zz_probe("", "use parts.{gone}
gone
")}<<<") false }
    then "c: control, nothing missing" { println("C>>>${zz_probe("", "use parts.{Part}
1
")}<<<") false }
}
EOF
