p='/work/avra/packages/std-avrac/src/compiler/law_findings.av'
s=open(p).read()
def rep(a,b):
    global s
    assert s.count(a)==1,a
    s=s.replace(a,b)
rep('''use @std.path.{dir_of, joined_path, normalized}
''','''use @std.path.{dir_of, joined_path, normalized}
use @std.program.source_facts.{source_octets, source_text}

extern fn avra_utf8_bad_at(b: Bytes) -> int
''')
rep('''/// How many findings in the written items of `file` fail a build: each of a law that refuses rather
/// than warns.
@query
export fn file_erring(engine: QueryEngine, file: SourceFileAddress) -> FileErring {
    FileErring {
        errors: [f for at in 0..item_count(engine, file) for f in law_findings(engine, file, at).findings if fails_build(f)]
            .length,
    }
}''','''/// How many findings in the written items of `file` fail a build: each of a law that refuses rather
/// than warns, and a source that holds no text.
@query
export fn file_erring(engine: QueryEngine, file: SourceFileAddress) -> FileErring {
    let absent = if source_standing(engine, file) is .Text { 0 } else { 1 }
    FileErring {
        errors: absent +
            [f for at in 0..item_count(engine, file) for f in law_findings(engine, file, at).findings if fails_build(f)]
                .length,
    }
}

/// What a source the program lists holds: its text, or why it holds none — no file there, octets
/// that are no text (from the byte that isn't), a host that would not give them, or a link that
/// leads nowhere.
@derive(Saved)
export enum SourceStanding {
    Text
    Missing
    NotText(at: int)
    Refused(why: string)
    Dangling
}

/// What the source `file` holds.
@query
export fn source_standing(engine: QueryEngine, file: SourceFileAddress) -> SourceStanding {
    if source_text(engine, file) != null { return SourceStanding.Text }
    match source_octets(engine, file) {
        .Read(octets) -> SourceStanding.NotText(avra_utf8_bad_at(octets)),
        .Missing -> SourceStanding.Missing,
        .Linked -> SourceStanding.Dangling,
        .Refused(why) -> SourceStanding.Refused(why),
    }
}''')
open(p,'w').write(s)

p='/work/avra/packages/std-avrac/src/compiler/item_said.av'
s=open(p).read()
rep('''/// The diagnostics every law finds in the file `h`, item by item.
export fn file_law_diags(engine: QueryEngine, h: ProgramFile) -> List<Diag> {
    [d! for at in 0..item_count(engine, h.file) for f in findings_in_file(engine, h.file, at) for d in [finding_diag(f, h.full)] if d != null]
}''','''/// The diagnostics every law finds in the file `h`, item by item, after what a source that holds no
/// text says of itself.
export fn file_law_diags(engine: QueryEngine, h: ProgramFile) -> List<Diag> {
    some_list(standing_said(source_standing(engine, h.file), h.full))
        .concat(
            [d! for at in 0..item_count(engine, h.file) for f in findings_in_file(engine, h.file, at) for d in [finding_diag(f, h.full)] if d != null],
        )
}

/// What a source the program lists says of itself where it holds no text, in its cause's words.
export fn standing_said(standing: SourceStanding, path: string) -> Diag? {
    let at = Loc { file: path, lo: 0, hi: 0 }
    match standing {
        .Text -> null,
        .Missing -> said_as("source.missing", at, missing_voice(path)),
        .NotText(byte) -> said_as("source.not_text", at, not_text_voice(path, byte)),
        .Refused(why) -> said_as("source.refused", at, refused_voice(path, why)),
        .Dangling -> said_as("source.dangling", at, dangling_voice(path)),
    }
}

/// A source the package lists that no file stands at.
fn missing_voice(path: string) -> Voice {
    Voice {
        message: "`${path}` does not exist",
        label: "listed here, and nothing stands here",
        help: "write the file, or take it out of the package",
    }
}

/// A source whose octets are no text, from the byte `at`.
fn not_text_voice(path: string, at: int) -> Voice {
    Voice {
        message: "`${path}` is not UTF-8 — byte ${at}",
        label: "a source is text",
        help: "save the file as UTF-8, or move what isn't source out of `src/`",
    }
}

/// A source the host would not give, in its own words.
fn refused_voice(path: string, why: string) -> Voice {
    Voice {
        message: "`${path}` can't be read — ${why}",
        label: "the host refused it",
        help: "give the file a mode the build can read",
    }
}

/// A source that is a link leading nowhere.
fn dangling_voice(path: string) -> Voice {
    Voice {
        message: "`${path}` is a link to nothing",
        label: "the link stands here",
        help: "point the link at a file, or take it away",
    }
}''')
rep('use diagnostics.{Diag, has_errors}','use diagnostics.{Diag, Voice, has_errors, said_as}')
open(p,'w').write(s)
EOF
