@input
fn language_print(_engine: QueryEngine) -> string { current_world().language_print }

/// A file's text, absent when there's none.
@input
export fn source_text(engine: QueryEngine, file: SourceFileAddress) -> string? {
    let world = current_world()
    let places? = world.places else { return (world.read_file)(file) }
    read_stamped(engine, (places.file)(file), () -> (world.read_file)(file))
}

/// A file's octets, read whatever they hold: a file a build reads as data rather than source.
@input
export fn source_octets(engine: QueryEngine, file: SourceFileAddress) -> FileOctets {
    let world = current_world()
    let places? = world.places else { return (world.read_octets)(file) }
    read_stamped(engine, (places.file)(file), () -> (world.read_octets)(file))
}

/// What a read of a file's octets found: them, no file, a link on the way to it, or why the host
/// would not give them.
@derive(Saved)
export enum FileOctets { Read(octets: Bytes), Missing, Linked, Refused(why: string) }

/// A world that reads no file's octets.
fn unread_octets(_file: SourceFileAddress) -> FileOctets { FileOctets.Missing }

/// The names in a directory, absent when there's none, in one order whatever order the host
/// lists them in.
@input
export fn listed(engine: QueryEngine, dir: DirectoryAddress) -> List<string>? {
    let world = current_world()
    let places? = world.places else { return names_in(world, dir) }
    read_stamped(engine, (places.directory)(dir), () -> names_in(world, dir))
}

/// The names `world` lists in `dir`, in text order; absent when there's no such directory.
fn names_in(world: SourceWorld, dir: DirectoryAddress) -> List<string>? {
    let names? = (world.list_directory)(dir) else { return null }
    sorted_by(names, text_before)
}

/// One item: what its part is called, and the hashes of what it says.
@derive(Saved)
type WrittenItem = { part_name: string, signature: ContentHash, body: ContentHash?, above: ContentHash }

/// Where one item sits in its file's text.
impl Held {
    /// Where a package's path stands.
    fn standing(package: string, path: string) -> string {
        let dir = package_stands(package, self.name, self.root, self.std, self.deps)
        if path.is_empty() { dir } else { "${dir}/${path}" }
    }

    /// A file's text; absent when it holds none there.
    fn read(file: SourceFileAddress) -> string? {
        let path = self.standing(file.package_name, file.path_in_package)
        self.asked.put(path, (self.asked.get().get(path) ?? 0) + 1)
        self.files.get(path)
    }

    /// How many times the text of the file standing at `path` was asked for.
    fn reads_of(path: string) -> int { self.asked.get().get(path) ?? 0 }

    /// Every file the layer asked for the text of.
    fn files_read() -> List<string> { self.asked.get().keys() }

    /// The most any one file under the directory `dir` was asked for.
    fn most_reads_under(dir: string) -> int {
        [n for path, n in self.asked.get() if path.starts_with("${dir}/")]
            .fold(0, (most, n) -> if n > most { n } else { most })
    }

    /// A file's octets, for a build that reads it as data.
    fn octets(file: SourceFileAddress) -> FileOctets {
        let text? = self.read(file) else { return FileOctets.Missing }
        FileOctets.Read(text.bytes())
    }

    /// The names directly in a directory; absent when nothing it holds lies under it.
    fn listed(dir: DirectoryAddress) -> List<string>? {
        let at = self.standing(dir.package_name, dir.path_in_package)
        let under = [path.substring(at.length + 1, path.length) for path in self.files.keys() if path.starts_with("${at}/")]
        if under.is_empty() { return null }
        distinct(
            [if rest.contains("/") { rest.substring(0, rest.index_of("/")) } else { rest } for rest in under],
        )
    }
