fn proof_ws_of(main: string) -> Workspace {
    test_workspace(memory_host({"/w/src/main.av": main}, ["/w/src/main.av"]), "/w")
}

fn analysed_of(a: Analysis) -> Analysed {
    Analysed { view: a.view, names: a.names, facts: a.facts }
    given "a `use` line naming two items, one of them read nowhere" {
        then "one Application, ACCEPTED by law — the line rewritten around the one item still read" {
            let text = "use lib.{Thing, Other}\nfn f() -> Thing {\n    Thing { x: 0 }\n}\n0\n"
            let apps = fix_apps_of_files(
                {
                    "/w/src/main.av": text,
                    "/w/src/lib.av": "export type Thing = { x: int }\nexport type Other = { y: int }\n",
                },
                ["/w/src/main.av", "/w/src/lib.av"],
            )
            apps.length == 1 &&
                apps[0].by_law != null &&
                apps[0].kind == "modules.unused_import" &&
                fix_applied(text, apps) == "use lib.{Thing}\nfn f() -> Thing {\n    Thing { x: 0 }\n}\n0\n"
        }
    }
    given "a `use` line whose only item is read nowhere" {
        then "the whole line is gone — its own trailing break kept, same as any statement's deletion" {
            let text = "use lib.{Other}\n0\n"
            let apps = fix_apps_of_files(
                {"/w/src/main.av": text, "/w/src/lib.av": "export type Other = { y: int }\n"},
                ["/w/src/main.av", "/w/src/lib.av"],
            )
            apps.length == 1 && fix_applied(text, apps) == "\n0\n"
        }
    }
}

